tn-primary' }} w-100 mt-auto" data-subscribe data-plan="{{ $plan->key }}">{{ $snapshot && $plan->key===$snapshot['key']?'Renouveler':'Choisir la durée' }}</button>@endif</article>@endforeach</div></section>
