@push('scripts')<script>
(()=>{const fmt=new Intl.NumberFormat('fr-FR'),dateFmt=new Intl.DateTimeFormat('fr-FR'),today=new Date();const expiry=(months,card)=>{const currentRank=Number(card.dataset.currentRank),planRank=Number(card.dataset.planRank),base=planRank>currentRank||!card.dataset.currentEnds?today:new Date(card.dataset.currentEnds),d=new Date(base);d.setMonth(d.getMonth()+months);return dateFmt.format(d)};const options=Array.from({length:12},(_,i)=>{const months=i+1;return `<button type="button" class="saas-month-option${months===1?' is-selected':''}" data-modal-month="${months}" aria-selected="${months===1?'true':'false'}">${months} mois</button>`}).join('');document.querySelectorAll('[data-plan-card]').forEach(card=>{const button=card.querySelector('[data-subscribe]');if(!button)return;button.addEventListener('click',()=>{let selectedMonths=1;const modalHtml=`<p class="mb-1"><b>${card.dataset.planName}</b></p><div class="saas-modal-duration"><span class="saas-duration-label">Durée souhaitée</span><div class="saas-months-picker" role="listbox" aria-label="Choisir la durée de l’abonnement" data-modal-months-list>${options}</div></div><div class="saas-modal-summary"><div>Montant total : <strong data-modal-total></strong></div><div data-modal-expiry></div><div class="saas-modal-discount" data-modal-discount></div></div>`;const refreshModal=()=>{const months=selectedMonths,monthly=Number(card.dataset.monthly),annual=Number(card.dataset.annual),amount=months===12?annual:monthly*months,total=document.querySelector('[data-modal-total]'),date=document.querySelector('[data-modal-expiry]'),discount=document.querySelector('[data-modal-discount]');if(total)total.textContent=fmt.format(amount)+' FCFA';if(date)date.innerHTML='Expiration estimée : <strong>'+expiry(months,card)+'</strong>';if(discount)discount.textContent=months===12?'Réduction annuelle appliquée (1 mois offert)':'Aucune réduction pour cette durée'};Swal.fire({title:'Préparer votre abonnement',html:modalHtml,icon:'question',showCancelButton:true,confirmButtonText:'Confirmer la durée',cancelButtonText:'Annuler',showLoaderOnConfirm:true,allowOutsideClick:()=>!Swal.isLoading(),didOpen:()=>{document.querySelectorAll('[data-modal-month]').forEach(option=>option.addEventListener('click',()=>{selectedMonths=Number(option.dataset.modalMonth);document.querySelectorAll('[data-modal-month]').forEach(item=>{const active=item===option;item.classList.toggle('is-selected',active);item.setAttribute('aria-selected',active?'true':'false')});refreshModal()}));refreshModal()},preConfirm:()=>{const months=selectedMonths;if(months<1||months>12){Swal.showValidationMessage('Choisissez une durée comprise entre 1 et 12 mois.');return false}return fetch(@json(route('subscriptions.checkout')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({plan:card.dataset.plan,months})}).then(r=>r.json().then(d=>{if(!r.ok||!d.status)throw new Error(d.msg||'Paiement impossible');return d})).then(d=>window.location.assign(d.checkout_url)).catch(e=>Swal.showValidationMessage(e.message))}})})})})();
</script>@endpush
